with with_windows as (select *, sum(budget) over w_recent cumulative_budget, dense_rank() over (partition by location order by budget) budget_dense_rank, ntile(5) over w_ordered budget_bucket from departments window w_recent as (partition by dept_name, location order by budget, id rows between unbounded preceding and current row), w_ordered as (order by budget, id)) select case when budget_dense_rank >= 9 then 'LARGE' else 'SMALL' end as budget_dense_rank_tier, location, case when cumulative_budget >= 20400184 then 'LARGE' else 'SMALL' end as cumulative_budget_tier, approx_percentile(budget_bucket, array(0.25, 0.5, 0.75)) as budget_bucket_quartiles, approx_percentile(budget_bucket, 0.9) as budget_bucket_p90, sort_array(collect_set(dept_name)) as dept_name_list, percentile_approx(budget_dense_rank, 0.5) as budget_dense_rank_p50, percentile_approx(budget_dense_rank, 0.5) as budget_dense_rank_p50_2, sum(case when dept_name = 'Sales' then budget_dense_rank else 0 end) as sales_budget_dense_rank from with_windows group by 1, 2, 3 having budget_bucket_p90 < 0
